def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding paths of K moves starting at any empty grid cell."""
    if K >= H * W:
        return 0

    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == "."]
    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = []
    for r, c in cells:
        adjacent = []
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            j = index.get((nr, nc))
            if j is not None:
                adjacent.append(j)
        neighbors.append(adjacent)

    total = 0

    def visit(cell: int, remaining: int, used: int) -> int:
        if remaining == 0:
            return 1
        subtotal = 0
        for nxt in neighbors[cell]:
            bit = 1 << nxt
            if not used & bit:
                subtotal += visit(nxt, remaining - 1, used | bit)
        return subtotal

    for start in range(len(cells)):
        total += visit(start, K, 1 << start)
    return total

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether s can be transformed into t using at most k edits."""
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t:
        return True

    # Keep only distances up to k; larger values cannot lead to a valid result.
    limit = k + 1
    previous = [limit] * (m + 1)
    for j in range(min(m, k) + 1):
        previous[j] = j

    for i, source_char in enumerate(s, 1):
        current = [limit] * (m + 1)
        if i <= k:
            current[0] = i
        start = max(1, i - k)
        end = min(m, i + k)
        row_min = limit
        for j in range(start, end + 1):
            substitution = previous[j - 1] + (source_char != t[j - 1])
            deletion = previous[j] + 1
            insertion = current[j - 1] + 1
            value = min(substitution, deletion, insertion, limit)
            current[j] = value
            if value < row_min:
                row_min = value
        if row_min > k:
            return False
        previous = current

    return previous[m] <= k

