def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """ Takahashi and Aoki play a card game. Initially, Takahashi has n cards, Aoki has m cards,
    and there are l cards on the table. Starting with Takahashi, they take turns:
    - Play one card from hand to table
    - Optionally take one card from table that has a smaller number than the played card

    The player who cannot make a move loses. Both players play optimally.

    Args:
        n: Number of cards in Takahashi's hand
        m: Number of cards in Aoki's hand
        l: Number of cards on the table
        takahashi_cards: List of card values in Takahashi's hand
        aoki_cards: List of card values in Aoki's hand
        table_cards: List of card values on the table

    Returns:
        "Takahashi" if Takahashi wins, "Aoki" if Aoki wins
    """
    @lru_cache(None)
    def winning(hand_t: Tuple[int, ...], hand_a: Tuple[int, ...],
                table: Tuple[int, ...], turn: int) -> bool:
        hand = hand_t if turn == 0 else hand_a
        if not hand:
            return False

        next_turn = 1 - turn
        for i, played in enumerate(hand):
            remaining = hand[:i] + hand[i + 1:]
            # Put the played card on the table without taking another card.
            if turn == 0:
                if not winning(remaining, hand_a, tuple(sorted(table + (played,))), next_turn):
                    return True
            else:
                if not winning(hand_t, remaining, tuple(sorted(table + (played,))), next_turn):
                    return True

            # Or exchange it for a smaller card already on the table.
            for j, taken in enumerate(table):
                if taken >= played:
                    break
                new_table = tuple(sorted(table[:j] + table[j + 1:] + (played,)))
                new_hand = tuple(sorted(remaining + (taken,)))
                if turn == 0:
                    if not winning(new_hand, hand_a, new_table, next_turn):
                        return True
                else:
                    if not winning(hand_t, new_hand, new_table, next_turn):
                        return True
        return False

    return "Takahashi" if winning(tuple(sorted(takahashi_cards)),
                                  tuple(sorted(aoki_cards)),
                                  tuple(sorted(table_cards)), 0) else "Aoki"

from typing import List, Tuple
from functools import lru_cache


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    tiles = tiles[:n]
    full = (1 << (h * w)) - 1

    # Precompute every placement mask for each tile orientation.
    placements = []
    for a, b in tiles:
        dims = {(a, b), (b, a)}
        options = []
        for ph, pw in dims:
            if ph > h or pw > w:
                continue
            for r in range(h - ph + 1):
                for c in range(w - pw + 1):
                    mask = 0
                    rowmask = (1 << pw) - 1
                    for rr in range(r, r + ph):
                        mask |= rowmask << (rr * w + c)
                    options.append((r, c, ph, pw, mask))
        placements.append(options)

    @lru_cache(None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        free = h * w - occupied.bit_count()
        area_left = sum(tiles[i][0] * tiles[i][1] for i in range(n) if not (used >> i) & 1)
        if area_left < free:
            return False

        # First uncovered cell gives a canonical next position.
        bit = ((~occupied) & full) & -((~occupied) & full)
        idx = bit.bit_length() - 1
        r, c = divmod(idx, w)

        for i, (a, b) in enumerate(tiles):
            if (used >> i) & 1:
                continue
            dims = {(a, b), (b, a)}
            for ph, pw in dims:
                if ph > h or pw > w:
                    continue
                # The tile must include the selected cell; reject any placement
                # overlapping cells already assigned.
                for top in range(max(0, r - ph + 1), r + 1):
                    if top + ph > h:
                        continue
                    for left in range(max(0, c - pw + 1), c + 1):
                        if left + pw > w:
                            continue
                        mask = 0
                        rowmask = ((1 << pw) - 1) << left
                        for rr in range(top, top + ph):
                            mask |= rowmask << (rr * w)
                        if not (mask & occupied) and search(occupied | mask, used | (1 << i)):
                            return True
        return False

    return search(0, 0)

