def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of scores of all good sequences modulo 998244353.

    A good sequence has length from 1 through n, with elements in [1, m].
    Its score is the number of positive divisors of the product of its elements.
    """
    mod = 998244353
    if m == 1:
        return n % mod

    primes = [p for p in (2, 3, 5, 7, 11, 13) if p <= m]
    valuations = {}
    for p in primes:
        opts = []
        for x in range(1, m + 1):
            y, exponent = x, 0
            while y % p == 0:
                y //= p
                exponent += 1
            if exponent:
                opts.append((x, exponent))
        valuations[p] = opts

    # S(q,j), Stirling numbers of the second kind, for q,j <= 6.
    stirling = [[0] * 7 for _ in range(7)]
    stirling[0][0] = 1
    for q in range(1, 7):
        for j in range(1, q + 1):
            stirling[q][j] = stirling[q - 1][j - 1] + j * stirling[q - 1][j]

    # Expand tau(product) = product_p (1 + sum_x v_p(x) C_x).
    # Then C_x^q = sum_j S(q,j) (C_x)_j.
    coeff = [0] * 7
    coeff[0] = 1
    from itertools import combinations, product
    for size in range(1, len(primes) + 1):
        for chosen in combinations(primes, size):
            for assignment in product(*(valuations[p] for p in chosen)):
                weight, counts = 1, {}
                for x, exponent in assignment:
                    weight = weight * exponent % mod
                    counts[x] = counts.get(x, 0) + 1
                terms = [(0, weight)]
                for q in counts.values():
                    terms = [
                        (degree + j, value * stirling[q][j] % mod)
                        for degree, value in terms
                        for j in range(1, q + 1)
                        if stirling[q][j]
                    ]
                for degree, value in terms:
                    coeff[degree] = (coeff[degree] + value) % mod

    inv_m = pow(m, mod - 2, mod)
    inv_powers = [1] * 7
    for i in range(1, 7):
        inv_powers[i] = inv_powers[i - 1] * inv_m % mod
    coeff = [c * inv_powers[i] % mod for i, c in enumerate(coeff)]

    # Taylor expansion of sum_{k=1}^n x^k = (x^(n+1)-x)/(x-1)
    # at x=m. Its Tth derivative is sum_k (k)_T m^(k-T).
    factorial = [1] * 7
    for i in range(1, 7):
        factorial[i] = factorial[i - 1] * i % mod
    inv_factorial = [pow(factorial[i], mod - 2, mod) for i in range(7)]
    numerator = [0] * 7
    for j in range(7):
        falling = 1
        for a in range(j):
            falling = falling * ((n + 1 - a) % mod) % mod
        choose = falling * inv_factorial[j] % mod
        numerator[j] = choose * pow(m, n + 1 - j, mod) % mod
    numerator[0] = (numerator[0] - m) % mod
    numerator[1] = (numerator[1] - 1) % mod

    inv_m1 = pow(m - 1, mod - 2, mod)
    denominator_inverse = [
        pow(-1, j, mod) * pow(inv_m1, j + 1, mod) % mod
        for j in range(7)
    ]
    answer = 0
    for degree in range(7):
        taylor = sum(numerator[j] * denominator_inverse[degree - j]
                     for j in range(degree + 1)) % mod
        answer = (answer + coeff[degree] * taylor * factorial[degree]) % mod
    return answer

from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Play the described card game with optimal play.

    A played card is put on the table. A smaller table card may be taken
    back into the player's hand. A player with no card to play loses.
    """
    # Cards are represented by indices so equal-valued cards remain distinct.
    values = tuple(takahashi_cards + aoki_cards + table_cards)
    t0 = tuple(range(n))
    a0 = tuple(range(n, n + m))
    table0 = tuple(range(n + m, n + m + l))

    @lru_cache(None)
    def win(turn: int, th: Tuple[int, ...], ah: Tuple[int, ...], table: Tuple[int, ...]) -> bool:
        hand = th if turn == 0 else ah
        if not hand:
            return False
        other = ah if turn == 0 else th
        # Playing a card is always legal; taking a smaller table card is optional.
        for card in hand:
            remaining = tuple(x for x in hand if x != card)
            placed = tuple(sorted(table + (card,)))
            # Passing on a capture is a legal move.
            if turn == 0:
                if not win(1, remaining, ah, placed):
                    return True
            else:
                if not win(0, th, remaining, placed):
                    return True
            for captured in table:
                if values[captured] < values[card]:
                    next_hand = tuple(sorted(remaining + (captured,)))
                    next_table = tuple(sorted(x for x in placed if x != captured))
                    if turn == 0:
                        if not win(1, next_hand, ah, next_table):
                            return True
                    else:
                        if not win(0, th, next_hand, next_table):
                            return True
        return False

    return "Takahashi" if win(0, t0, a0, table0) else "Aoki"

