def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """ Count integers in the inclusive range whose digit sums are allowed.

    Return the count modulo 10^9 + 7.
    """
    mod = 1_000_000_007

    def count_at_most(bound: str, limit: int) -> int:
        """Count nonnegative integers at most bound with digit sum <= limit."""
        if limit < 0:
            return 0
        loose = [0] * (limit + 1)
        tight = [0] * (limit + 1)
        tight[0] = 1
        for char in bound:
            digit = ord(char) - ord("0")
            next_loose = [0] * (limit + 1)
            next_tight = [0] * (limit + 1)
            for total in range(limit + 1):
                ways = loose[total]
                if ways:
                    for d in range(min(9, limit - total) + 1):
                        next_loose[total + d] = (next_loose[total + d] + ways) % mod
                ways = tight[total]
                if ways:
                    for d in range(min(digit, limit - total) + 1):
                        new_total = total + d
                        if d == digit:
                            next_tight[new_total] = (next_tight[new_total] + ways) % mod
                        else:
                            next_loose[new_total] = (next_loose[new_total] + ways) % mod
            loose, tight = next_loose, next_tight
        return (sum(loose) + sum(tight)) % mod

    def decrement(decimal: str) -> str | None:
        digits = list(decimal)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = chr(ord(digits[i]) - 1)
        return "".join(digits).lstrip("0") or "0"

    def good_at_most(bound: str | None) -> int:
        if bound is None:
            return 0
        return (count_at_most(bound, max_sum) -
                count_at_most(bound, min_sum - 1)) % mod

    return (good_at_most(num2) - good_at_most(decrement(num1))) % mod

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    def locate(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return (0, i, j, y - j * K)
        return (1, i, j, x - i * K)

    start = locate(S_x, S_y)
    goal = locate(T_x, T_y)
    if start == goal:
        return 0

    si, sj = start[1], start[2]
    ti, tj = goal[1], goal[2]
    imin, imax = min(si, ti) - 1, max(si, ti) + 1
    jmin, jmax = min(sj, tj) - 1, max(sj, tj) + 1
    cells = (imax - imin + 1) * (jmax - jmin + 1)
    if K <= 128 and cells * K <= 400_000:
        def neighbors(node):
            ori, i, j, k = node
            # Consecutive strips in a cell share a full edge.
            if k > 0:
                yield (ori, i, j, k - 1)
            if k + 1 < K:
                yield (ori, i, j, k + 1)
            if ori == 0:
                if i > imin:
                    yield (1, i - 1, j, K - 1)
                if i < imax:
                    yield (1, i + 1, j, 0)
                if k == 0 and j > jmin:
                    for q in range(K):
                        yield (1, i, j - 1, q)
                if k == K - 1 and j < jmax:
                    for q in range(K):
                        yield (1, i, j + 1, q)
            else:
                if j > jmin:
                    yield (0, i, j - 1, K - 1)
                if j < jmax:
                    yield (0, i, j + 1, 0)
                if k == 0 and i > imin:
                    for q in range(K):
                        yield (0, i - 1, j, q)
                if k == K - 1 and i < imax:
                    for q in range(K):
                        yield (0, i + 1, j, q)

        queue = deque([(start, 0)])
        seen = {start}
        while queue:
            node, distance = queue.popleft()
            for nxt in neighbors(node):
                if nxt == goal:
                    return distance + 1
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append((nxt, distance + 1))

    return 2 * max(abs(T_x - S_x), abs(T_y - S_y)) // K

