def count_in_degree_sequences(n: int, s: str) -> int:
    """ Given a positive integer n and a string s of length n consisting of '0' and '1',
    construct a graph G with (n+1) vertices numbered 0 to n, with the following edges:
    - For each i from 0 to n-1, there's an edge between vertices i and (i+1) mod n
    - For each i from 0 to n-1, there's an edge between vertices i and n if s[i] == '1'

    Create a directed graph G' by assigning a direction to each edge of G.
    For each vertex i, let d_i be its in-degree in G'.

    Return the number of distinct sequences (d_0, d_1, ..., d_n) that can be obtained,
    modulo 998244353.

    Args:
        n: A positive integer (3 <= n <= 10^6)
        s: A string of length n consisting only of '0' and '1'

    Returns:
        The number of distinct in-degree sequences modulo 998244353

    >>> count_in_degree_sequences(3, '010')
    14
    >>> count_in_degree_sequences(20, '00001100111010100101')
    261339902
    """
    mod = 998244353

    # For each edge of the cycle, let a_i be 1 when it points from i to i+1.
    # Then the cycle contribution to vertex i is 1 + a_{i-1} - a_i.
    # A spoke at i adds a freely chosen bit, so after subtracting 1 the
    # observable coordinate is z_i = a_{i-1} - a_i (+ b_i when s[i] is 1).
    #
    # Count distinct observable words with a two-state nondeterministic
    # automaton. A state of the determinized automaton is a binary relation
    # between the bit before the processed positions and the current bit.
    # Keeping the whole relation preserves all possible cycle orientations;
    # a word is valid exactly when its final relation has a diagonal entry.
    transitions = []
    for has_spoke in (False, True):
        by_label = {}
        for label in range(-1, 3):
            edge_mask = 0
            for previous in (0, 1):
                for current in (0, 1):
                    difference = previous - current
                    for spoke_bit in ((0, 1) if has_spoke else (0,)):
                        if difference + spoke_bit == label:
                            edge_mask |= 1 << (previous * 2 + current)
            if edge_mask:
                by_label[label] = edge_mask
        # For each relation and each output label, precompute the composed
        # relation. Relation bit (p,q) means a path from p to q exists.
        table = [[0] * 16 for _ in range(16)]
        for relation in range(16):
            for edge_mask in by_label.values():
                composed = 0
                for previous in (0, 1):
                    reachable = (relation >> (previous * 2)) & 0b11
                    for current in (0, 1):
                        if edge_mask & (1 << (previous * 2 + current)):
                            composed |= reachable << (current * 2)
                table[relation][edge_mask] = composed
        transitions.append((by_label, table))

    # The above table is keyed by edge mask, not output label; keep compact
    # per-position transition entries to avoid any ambiguity from equal masks.
    relation_moves = []
    for has_spoke in (False, True):
        moves = [[] for _ in range(16)]
        by_label, _ = transitions[has_spoke]
        for label, edge_mask in by_label.items():
            for relation in range(16):
                composed = 0
                for previous in (0, 1):
                    reachable = (relation >> (previous * 2)) & 0b11
                    for current in (0, 1):
                        if edge_mask & (1 << (previous * 2 + current)):
                            composed |= reachable << (current * 2)
                moves[relation].append(composed)
        relation_moves.append(moves)

    dp = [0] * 16
    dp[(1 << 0) | (1 << 3)] = 1  # identity relation
    for bit in s:
        moves = relation_moves[bit == "1"]
        nxt = [0] * 16
        for relation, ways in enumerate(dp):
            if ways:
                for new_relation in moves[relation]:
                    nxt[new_relation] = (nxt[new_relation] + ways) % mod
        dp = nxt

    return sum(dp[relation] for relation in range(16) if relation & 0b1001) % mod

