def expected_operations(N: int, M: int) -> int:
    """Calculate the expected number of operations Takahashi performs on the tree."""
    mod = 998244353
    inv = [0] * (N + 1)
    if N >= 1:
        inv[1] = 1
    for i in range(2, N + 1):
        inv[i] = mod - (mod // i) * inv[mod % i] % mod
    harmonic = sum(inv[1:]) % mod
    return (M * M % mod) * ((2 * N * harmonic - 1) % mod) % mod

from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Return the minimum cost of sensors covering every section, subject to global limits."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    if n == 0:
        return 0

    # A state records the two sensor counts used and the cheapest cost reaching it.
    states = {(0, 0): 0}
    for distance in sections[:n]:
        # For each possible type-1 count, only the least type-2 count needed
        # for this section can be useful (all costs are nonnegative).
        options = []
        max_first = min(k1, (distance + l1 - 1) // l1)
        for first in range(max_first + 1):
            remaining = max(0, distance - first * l1)
            second = (remaining + l2 - 1) // l2
            if second <= k2:
                options.append((first, second, first * c1 + second * c2))
        if not options:
            return -1

        next_states = {}
        for (used1, used2), cost in states.items():
            for add1, add2, add_cost in options:
                total1 = used1 + add1
                total2 = used2 + add2
                if total1 <= k1 and total2 <= k2:
                    key = (total1, total2)
                    value = cost + add_cost
                    if value < next_states.get(key, float("inf")):
                        next_states[key] = value
        if not next_states:
            return -1

        # Remove states that use at least as many sensors of both types and
        # cost at least as much as another state.
        ordered = sorted((a, b, c) for (a, b), c in next_states.items())
        kept = {}
        for a, b, cost in ordered:
            dominated = False
            for (x, y), old_cost in kept.items():
                if x <= a and y <= b and old_cost <= cost:
                    dominated = True
                    break
            if not dominated:
                # Existing states dominated by this one can no longer help.
                for key in list(kept):
                    x, y = key
                    if a <= x and b <= y and cost <= kept[key]:
                        del kept[key]
                kept[(a, b)] = cost
        states = kept

    return min(states.values()) if states else -1

from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Given an undirected tree, return the largest alkane subgraph size."""
    if n < 5:
        return -1

    graph = [[] for _ in range(n)]
    for a, b in edges:
        a -= 1
        b -= 1
        graph[a].append(b)
        graph[b].append(a)

    parent = [-2] * n
    parent[0] = -1
    order = [0]
    for v in order:
        for w in graph[v]:
            if w != parent[v]:
                parent[w] = v
                order.append(w)

    arm_any = [1] * n
    arm_branch = [0] * n
    best = -1

    for v in reversed(order):
        children = [w for w in graph[v] if parent[w] == v]
        child_arms = [arm_any[w] for w in children]
        child_branches = [arm_branch[w] for w in children]

        if len(child_arms) >= 3:
            branch_arm = 1 + sum(sorted(child_arms, reverse=True)[:3])
            arm_branch[v] = branch_arm
            arm_any[v] = max(1, branch_arm)

        for branch_size in child_branches:
            if branch_size:
                best = max(best, 1 + branch_size)

        if len(child_arms) >= 4:
            best = max(best, 1 + sum(sorted(child_arms, reverse=True)[:4]))

    # Two degree-4 centers can be linked by a two-edge connector whose
    # internal vertex has degree 2; that connector contributes one vertex.
    branch_vertices = [v for v in range(n) if len(graph[v]) == 4]
    if best == 5 and len(branch_vertices) >= 2:
        for i, a in enumerate(branch_vertices):
            seen = {a}
            stack = [(a, 0)]
            while stack:
                v, d = stack.pop()
                if d >= 3:
                    continue
                for w in graph[v]:
                    if w not in seen:
                        if w in branch_vertices[i + 1:] and d + 1 == 3:
                            best = max(best, 6)
                            break
                        seen.add(w)
                        stack.append((w, d + 1))
                if best == 6:
                    break
            if best == 6:
                break

    return best

