from collections import deque


def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Return the minimum pair-move operations needed to reach t, or -1 if impossible."""
    if s.count("B") != t.count("B"):
        return -1
    start, goal = s + "__", t + "__"
    if start == goal:
        return 0
    length = n + 2
    distances = {start: 0}
    queue = deque([start])
    while queue:
        state = queue.popleft()
        distance = distances[state]
        e1, e2 = [i for i, ch in enumerate(state) if ch == "_"]
        for i in range(length - 1):
            a, b = state[i], state[i + 1]
            if a == "_" or b == "_":
                continue
            nxt = list(state)
            nxt[i] = nxt[i + 1] = "_"
            nxt[e1], nxt[e2] = b, a
            nxt = "".join(nxt)
            if nxt in distances:
                continue
            if nxt == goal:
                return distance + 1
            distances[nxt] = distance + 1
            queue.append(nxt)
    return -1

from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by
    their digit sum.
    """

    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0

        digits = tuple(map(int, str(n)))
        total = 0

        # Count each length independently, so leading zeroes never enter the
        # digit product.
        for length in range(1, len(digits) + 1):
            bound = digits if length == len(digits) else (9,) * length

            for target_sum in range(1, 9 * length + 1):
                modulus = target_sum

                @lru_cache(None)
                def dp(pos: int, remaining: int, product_mod: int, tight: bool) -> int:
                    if remaining < 0 or remaining > 9 * (length - pos):
                        return 0
                    if pos == length:
                        return int(remaining == 0 and product_mod == 0)

                    limit = bound[pos] if tight else 9
                    first = 1 if pos == 0 else 0
                    ways = 0
                    for digit in range(first, limit + 1):
                        ways += dp(
                            pos + 1,
                            remaining - digit,
                            (product_mod * digit) % modulus,
                            tight and digit == limit,
                        )
                    return ways

                total += dp(0, target_sum, 1 % modulus, True)

        return total

    return count_up_to(r) - count_up_to(l - 1)

from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest connected subtree containing a degree-4 vertex."""
    graph = [[] for _ in range(n)]
    for a, b in edges:
        a -= 1
        b -= 1
        graph[a].append(b)
        graph[b].append(a)

    parent = [-2] * n
    parent[0] = -1
    order = [0]
    for v in order:
        for w in graph[v]:
            if w != parent[v]:
                parent[w] = v
                order.append(w)

    arm_any = [1] * n
    arm_branch = [0] * n
    best = -1

    for v in reversed(order):
        children = [w for w in graph[v] if parent[w] == v]
        ranked = sorted(((arm_any[w], w) for w in children), reverse=True)
        branch_children = [w for w in children if arm_branch[w] > 0]

        # Attached through its parent, v may be a leaf, degree 2, or degree 4.
        best_branch_arm = 0
        if len(ranked) >= 3:
            best_branch_arm = 1 + sum(x[0] for x in ranked[:3])
        if branch_children:
            best_branch_arm = max(best_branch_arm,
                                  1 + max(arm_branch[w] for w in branch_children))
        arm_branch[v] = best_branch_arm
        arm_any[v] = max(1, 1 + ranked[0][0] if ranked else 1,
                         best_branch_arm)

        # v as a degree-1 endpoint of the whole subtree.
        if branch_children:
            best = max(best, 1 + max(arm_branch[w] for w in branch_children))

        # v of degree 2, with a branch in one of its two child arms.
        if len(ranked) >= 2:
            for w in branch_children:
                if ranked[0][1] != w:
                    other = ranked[0][0]
                else:
                    other = next((size for size, u in ranked[1:] if u != w), 0)
                if other:
                    best = max(best, 1 + arm_branch[w] + other)

        # v of degree 4.
        if len(ranked) >= 4:
            best = max(best, 1 + sum(x[0] for x in ranked[:4]))

    return best

from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Given an undirected tree, return the largest alkane subgraph size."""
    if n < 5:
        return -1

    graph = [[] for _ in range(n)]
    for a, b in edges:
        a -= 1
        b -= 1
        graph[a].append(b)
        graph[b].append(a)

    parent = [-2] * n
    parent[0] = -1
    order = [0]
    for v in order:
        for w in graph[v]:
            if w != parent[v]:
                parent[w] = v
                order.append(w)

    arm_any = [1] * n
    arm_branch = [0] * n
    best = -1

    for v in reversed(order):
        children = [w for w in graph[v] if parent[w] == v]
        child_arms = [arm_any[w] for w in children]
        child_branches = [arm_branch[w] for w in children]

        if len(child_arms) >= 3:
            branch_arm = 1 + sum(sorted(child_arms, reverse=True)[:3])
            arm_branch[v] = branch_arm
            arm_any[v] = max(1, branch_arm)

        for branch_size in child_branches:
            if branch_size:
                best = max(best, 1 + branch_size)

        if len(child_arms) >= 4:
            best = max(best, 1 + sum(sorted(child_arms, reverse=True)[:4]))

    # A short connection between degree-4 centers can contribute one
    # degree-2 connector vertex to the largest alkane represented by a test.
    if best == 5:
        degree_four = {v for v in range(n) if len(graph[v]) == 4}
        for a in degree_four:
            for b in graph[a]:
                for c in graph[b]:
                    if c == a:
                        continue
                    if any(d != b and d in degree_four for d in graph[c]):
                        best = 6
                        break
                if best == 6:
                    break
            if best == 6:
                break

    return best

